supplemental.script:
import assert from "node:assert/strict";
import {readFileSync,existsSync} from "node:fs";
import path from "node:path";
const files=["docs/design/admission-use-lifecycle.md","docs/BOARD.md","docs/VERIFICATION.md"];
const slug=s=>s.trim().toLowerCase().replace(/<[^>]*>/gu,"").replace(/[`*_~]/gu,"").replace(/[.,:;!?()[\]{}'"\\/|<>@#$%^&+=]/gu,"").replace(/\s/gu,"-");
function headings(source){const seen=new Map(), out=new Set(); for(const line of source.split(/\r?\n/u)){const m=/^#{1,6}\s+(.+?)\s*$/u.exec(line); if(!m)continue; const b=slug(m[1]), n=seen.get(b)??0; seen.set(b,n+1);out.add(n===0?b:b+"-"+n);}return out;}
let total=0; const bad=[], counts={};const cache=new Map();
for(const file of files){const text=readFileSync(file,"utf8");counts[file]=0;assert(!/[^\x00-\x7f]/u.test(text),file+" non-ASCII");
for(const m of text.matchAll(/\]\(([^)\s#]*)(#[^)\s]*)?\)/gu)){const ref=m[1], fragment=m[2];if(/^(?:https?:|mailto:)/u.test(ref))continue;total++;counts[file]++;
const target=ref ? path.resolve(path.dirname(path.resolve(file)),ref) : path.resolve(file);
if(!existsSync(target)){bad.push({file,ref,error:"target missing"});continue;}
if(fragment&&target.endsWith(".md")){if(!cache.has(target))cache.set(target,headings(readFileSync(target,"utf8")));if(!cache.get(target).has(fragment.slice(1)))bad.push({file,ref:ref+fragment,error:"anchor missing"});}
}}
assert.deepEqual(bad,[]);
const proposed=readFileSync(files[0],"utf8");
assert(proposed.startsWith("# Admission use lifecycle proposal\n\nStatus: preliminary"));
assert.equal((proposed.match(/^## /gmu)||[]).length,10);
assert(!proposed.split("\n").some(line=>/[ \t]+$/u.test(line)));
console.log(JSON.stringify({pass:true,totalLocalLinks:total,byFile:counts,bad,scope:"target/anchor integrity, ASCII, trailing whitespace and declared draft structure only; not semantic or runtime assurance"},null,2));

